const input = items[0].json || {};
const body = input.body ?? input;
const question = typeof body.question === 'string' ? body.question.trim() : '';
const project_code = typeof body.project_code === 'string' ? body.project_code.trim() : '';
const workflow_code = typeof body.workflow_code === 'string' ? body.workflow_code.trim() : '';
const actor_id = typeof body.actor_id === 'string' && body.actor_id.trim()
  ? body.actor_id.trim()
  : (input.default_actor_id || 'n8n-webhook-project-qa');
const client_trace_id = typeof body.trace_id === 'string' ? body.trace_id.trim() : '';
const errors = [];

if (!input.gateway_url || typeof input.gateway_url !== 'string') {
  errors.push('gateway_url is required');
}
if (!input.gateway_key || typeof input.gateway_key !== 'string') {
  errors.push('gateway_key is required');
}
if (!question) {
  errors.push('question is required');
}
if (body.mode && body.mode !== 'answer') {
  errors.push('mode is locked to answer for this pilot');
}
if (body.task_type && body.task_type !== 'project_qa') {
  errors.push('task_type is locked to project_qa for this pilot');
}

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const ts = `${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const rand = Math.random().toString(36).slice(2, 8);
const trace_id = client_trace_id || `qa_${ts}_${rand}`;

const request_payload = {
  trace_id,
  mode: 'answer',
  task_type: 'project_qa',
  actor: {
    type: 'system',
    id: actor_id,
  },
  input: {
    question,
  },
  context: {
    include_context: Boolean(input.include_context),
    registry: {
      project_codes: project_code ? [project_code] : [],
      workflow_codes: workflow_code ? [workflow_code] : [],
      doc_scope: input.doc_scope || 'registry',
    },
  },
  options: {
    temperature: typeof input.temperature === 'number' ? input.temperature : 0.2,
    max_output_tokens: typeof input.max_output_tokens === 'number' ? input.max_output_tokens : 1200,
  },
  metadata: {
    source: 'n8n',
    workflow_name: input.workflow_name || 'AI Gateway - Project QA Webhook Production',
    workflow_version: input.workflow_version || 'v1',
    trigger: 'webhook',
    webhook_path: 'ai-gateway/project-qa',
  },
};

return [{
  json: {
    ...input,
    inbound_body: body,
    trace_id,
    question,
    project_code,
    workflow_code,
    actor_id,
    validation: {
      ok: errors.length === 0,
      errors,
    },
    request_payload,
  }
}];

return [{
  json: {
    ok: false,
    status: 'validation_failed',
    is_retriable: false,
    failure_stage: 'validation',
    http_status: 400,
    trace_id: $json.trace_id,
    task_type: 'project_qa',
    mode: 'answer',
    errors: $json.validation?.errors || ['validation failed'],
    request_preview: {
      question: $json.question || '',
      project_code: $json.project_code || '',
      workflow_code: $json.workflow_code || '',
      actor_id: $json.actor_id || '',
    },
  }
}];

const raw = items[0].json || {};
const statusCode = raw.statusCode || raw.status || 0;
const body = raw.body ?? {};
return [{
  json: {
    gateway_http_status: statusCode,
    gateway_headers: raw.headers || {},
    gateway_body: body,
    trace_id: body.trace_id || $json.trace_id || '',
    ok: body.ok === true,
    gateway_ok: body.ok === true,
  }
}];

const body = $json.gateway_body || {};
const result = body.result || body.output || {};
return [{
  json: {
    ok: true,
    status: 'completed',
    is_retriable: false,
    failure_stage: null,
    http_status: 200,
    trace_id: body.trace_id || $json.trace_id || '',
    run_id: body.run_id || result.run_id || null,
    provider: body.provider || result.provider || null,
    model: body.model || result.model || null,
    mode: body.mode || 'answer',
    task_type: body.task_type || 'project_qa',
    answer: result.answer || body.answer || body.output_text || '',
    citations: result.citations || body.citations || [],
    raw_result: result,
    gateway_response: body,
  }
}];

const body = $json.gateway_body || {};
const httpStatus = Number($json.gateway_http_status || 0);
const failureStage = body.failure_stage || (httpStatus === 401 || httpStatus === 403 ? 'auth' : 'execution');
const status = body.status || 'gateway_failed';
let responseStatus = 502;
if (failureStage === 'auth') responseStatus = 502;
if (failureStage === 'validation') responseStatus = 400;
if (httpStatus >= 400 && httpStatus < 500 && failureStage !== 'auth') responseStatus = 400;

return [{
  json: {
    ok: false,
    status,
    is_retriable: body.is_retriable === true,
    failure_stage: failureStage,
    http_status: responseStatus,
    trace_id: body.trace_id || $json.trace_id || '',
    task_type: body.task_type || 'project_qa',
    mode: body.mode || 'answer',
    error_message: body.error_message || body.message || body.error || 'AI Gateway request failed',
    error_detail: body.error_detail || body.details || body,
    gateway_http_status: httpStatus,
    gateway_response: body,
  }
}];
